	Kit.Disc(m, "CookingPot", 27, 22, CF(c + V(50, 13, -8)), C.Coral)
	Kit.Disc(m, "PotLid", 30, 2, CF(c + V(50, 25, -8)), C.Coral)
	Kit.Ball(m, "LidKnob", V(5, 5, 5), CF(c + V(50, 28, -8)), C.Gold)
	for _, x in ipairs({ -17, 17 }) do
