		local water = Kit.Ball(
			m,
			"FloatingWater",
			V(info[4], info[4], info[4]),
			cf,
			C.Cyan,
			Enum.Material.Glass
		)
		water.Transparency = 0.74
		Kit.Jellyfish(m, cf * CF(0, 4, 0), i == 2 and 1.3 or 0.9, i == 2 and C.Pink or C.Cyan)
	end
