    ["server/RiftGenerator"] = [=[
--!strict
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local sharedRef = script.Parent:FindFirstChild("SharedRef")
local Shared = sharedRef and sharedRef.Value or ReplicatedStorage:WaitForChild("OddvaultShared")
local Constants = require(Shared.Constants)
local Dimensions = require(Shared.DimensionDefinitions)
local Rooms = require(Shared.RoomDefinitions)
local Planner = require(Shared.GraphPlanner)
local Builder = require(script.Parent.WorldBuilder)
local Generator = {}
export type Statistics = {
	Instances: number,
	BaseParts: number,
	PhysicsParts: number,
	ParticleEmitters: number,
	Lights: number,
	NPCs: number,
	Artifacts: number,
	GenerationMilliseconds: number?,
}
export type Request = {
	RiftId: string,
	DimensionId: string,
	Seed: number,
	Difficulty: number,
	PartyId: string,
	CellId: string,
	Origin: Vector3,
}
export type Generated = {
	Model: Model,
	Graph: Planner.Graph,
	Rooms: { [number]: Model },
	Entry: BasePart,
	Extraction: BasePart,
	Statistics: Statistics,
}

local function hasTagUnder(model, tag)
	for _, object in ipairs(model:GetDescendants()) do
		if CollectionService:HasTag(object, tag) then
			return true
		end
	end
	return false
end

local function intersects(aMin, aMax, bMin, bMax)
	return aMin.X < bMax.X - 0.01
		and aMax.X > bMin.X + 0.01
		and aMin.Y < bMax.Y - 0.01
		and aMax.Y > bMin.Y + 0.01
		and aMin.Z < bMax.Z - 0.01
		and aMax.Z > bMin.Z + 0.01
end

local function localBounds(part, pivot)
	local cf = pivot:ToObjectSpace(part.CFrame)
	local size = part.Size / 2
	local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
	local extent = Vector3.new(
		math.abs(r.X) * size.X + math.abs(u.X) * size.Y + math.abs(l.X) * size.Z,
		math.abs(r.Y) * size.X + math.abs(u.Y) * size.Y + math.abs(l.Y) * size.Z,
		math.abs(r.Z) * size.X + math.abs(u.Z) * size.Y + math.abs(l.Z) * size.Z
	)
	return cf.Position - extent, cf.Position + extent
end

function Generator.ValidateTemplate(
	template: Model,
	definition: Builder.RoomDefinition
): { [string]: BasePart }
	assert(template:IsA("Model"), "Room template must be a Model")
	for _, key in ipairs({
		"RoomId",
		"Role",
		"Width",
		"Depth",
		"Height",
		"CarryWidth",
		"CarryHeight",
		"KitVersion",
	}) do
		assert(template:GetAttribute(key) == definition[key], "Room metadata mismatch: " .. key)
	end
	local pivot, parts = template:GetPivot(), 0
	local sockets, points = {}, template:FindFirstChild("Sockets")
	assert(points, "Missing sockets")
	for _, socket in ipairs(points:GetChildren()) do
		local direction = Planner.Directions[socket:GetAttribute("Direction")]
		assert(socket:IsA("BasePart") and direction, "Invalid socket direction")
		local key = socket:GetAttribute("Direction")
		assert(not sockets[key], "Duplicate socket direction")
		assert(CollectionService:HasTag(socket, "RiftSocket"), "Socket tag missing")
		assert(
			socket:GetAttribute("SocketType") == "Large"
				and socket:GetAttribute("AllowedConnections") == "Large",
			"Incompatible socket type"
		)
		assert(
			socket:GetAttribute("Width") >= Constants.CarryWidth
				and socket:GetAttribute("Height") >= Constants.CarryHeight,
			"Socket clearance too small"
		)
		assert(
			socket:GetAttribute("OneWay") == false,
			"One-way sockets unsupported in foundation kit"
		)
		local cf = pivot:ToObjectSpace(socket.CFrame)
		assert(
			(cf.Position - Vector3.new(direction.X * 48, 12, direction.Z * 48)).Magnitude < 0.01,
			"Socket off grid or off edge"
		)
		assert(
			cf.LookVector:Dot(Vector3.new(direction.X, 0, direction.Z)) > 0.999,
			"Socket must face outward"
		)
		sockets[key] = socket
	end
	for direction in pairs(Planner.Directions) do
		assert(sockets[direction], "Missing socket " .. direction)
	end
	assert(hasTagUnder(template, "RoomBounds"), "Missing room bounds")
	assert(hasTagUnder(template, "PlayerSpawn"), "Missing safe spawn")
	assert(hasTagUnder(template, "ArtifactSpawn"), "Missing curated artifact authoring marker")
	if definition.Role == "Extraction" then
		assert(hasTagUnder(template, "ExtractionPoint"), "Missing extraction point")
	end
	if definition.Role == "Landmark" then
		assert(hasTagUnder(template, "Landmark"), "Missing landmark")
	end
	local h = Constants.CarryWidth / 2
	local lanes = {
		{ Vector3.new(-h, 0, -48), Vector3.new(h, Constants.CarryHeight, 48) },
		{ Vector3.new(-48, 0, -h), Vector3.new(48, Constants.CarryHeight, h) },
	}
	local floorFound = false
	for _, object in ipairs(template:GetDescendants()) do
		if object:IsA("BasePart") then
			parts += 1
			local low, high = localBounds(object, pivot)
			if object.CanCollide then
				assert(
					low.X >= -48.01 and high.X <= 48.01 and low.Z >= -48.01 and high.Z <= 48.01,
					"Collision outside room footprint"
				)
				for _, lane in ipairs(lanes) do
					assert(
						not intersects(low, high, lane[1], lane[2]),
						"Collision blocks cargo lane: " .. object.Name
					)
				end
				if
					low.X <= -47.99
					and high.X >= 47.99
					and low.Z <= -47.99
					and high.Z >= 47.99
					and math.abs(high.Y) < 0.01
				then
					floorFound = true
				end
			end
			if
				CollectionService:HasTag(object, "PlayerSpawn")
				or CollectionService:HasTag(object, "ExtractionPoint")
			then
				local point = pivot:PointToObjectSpace(object.Position)
				assert(
					math.abs(point.X) <= h - 2
						and math.abs(point.Z) <= 44
						and point.Y >= 3
						and point.Y <= 8,
					"Unsafe spawn/extraction marker"
				)
			end
			assert(object.Anchored, "Phase 1 kit must contain only anchored geometry")
		end
	end
	assert(floorFound, "Room requires a continuous, level collision floor")
	assert(parts <= Constants.MaxPartsPerRoom, "Room exceeds part budget")
	return sockets
end

function Generator.Statistics(model: Model): Statistics
	local stats = {
		Instances = 0,
		BaseParts = 0,
		PhysicsParts = 0,
		ParticleEmitters = 0,
		Lights = 0,
		NPCs = 0,
		Artifacts = 0,
	}
	for _, object in ipairs(model:GetDescendants()) do
		stats.Instances += 1
		if object:IsA("BasePart") then
			stats.BaseParts += 1
			if not object.Anchored then
				stats.PhysicsParts += 1
			end
		elseif object:IsA("ParticleEmitter") then
			stats.ParticleEmitters += 1
		elseif object:IsA("Light") then
			stats.Lights += 1
		elseif object:IsA("Humanoid") then
			stats.NPCs += 1
		end
		if object:GetAttribute("ArtifactInstanceId") then
			stats.Artifacts += 1
		end
	end
	return stats
end

function Generator.Generate(templates: Folder, parent: Folder, request: Request): Generated
	local started = os.clock()
	local dimension = assert(Dimensions[request.DimensionId], "Unknown DimensionId")
	assert(request.Difficulty == 1, "Only foundation difficulty 1 is supported")
	local graph = Planner.Plan(request.Seed, dimension, Rooms, Constants)
	local valid, errors = Planner.Validate(graph, Rooms, Constants)
	assert(valid, table.concat(errors, "; "))
	local templateDirectory =
		assert(templates:FindFirstChild(dimension.DimensionId), "Missing dimension templates")
	local sourceRooms = assert(templateDirectory:FindFirstChild("Rooms"), "Missing Rooms")
	local checked = {}
	-- Fail before allocating Instances if any selected authored room is invalid.
	for _, node in ipairs(graph.Nodes) do
		if not checked[node.TemplateId] then
			local template =
				assert(sourceRooms:FindFirstChild(node.TemplateId), "Missing room template")
			Generator.ValidateTemplate(template, Rooms[node.TemplateId])
			checked[node.TemplateId] = template
		end
	end
	local model = Instance.new("Model")
	model.Name = "Rift_" .. request.RiftId
	local ok, result = pcall(function()
		for _, key in ipairs({ "RiftId", "DimensionId", "Seed", "Difficulty", "PartyId", "CellId" }) do
			model:SetAttribute(key, request[key])
		end
		model:SetAttribute("GenerationVersion", graph.GenerationVersion)
		model:SetAttribute("GraphFingerprint", Planner.Fingerprint(graph))
		model:SetAttribute("State", "Generating")
		model:SetAttribute("MainPathLength", graph.MainPathLength)
		local geometry = Builder.Folder(model, "Geometry")
		local gameplay = Builder.Folder(model, "Gameplay")
		for _, name in ipairs({ "Artifacts", "Hazards", "Players", "Effects" }) do
			Builder.Folder(model, name)
		end
		local origin, roomModels, used = request.Origin, {}, {}
		for _, node in ipairs(graph.Nodes) do
			local room = checked[node.TemplateId]:Clone()
			room.Name = "Room_" .. node.Id .. "_" .. node.TemplateId
			room:SetAttribute("NodeId", node.Id)
			room:SetAttribute("Optional", node.Optional)
			room:PivotTo(CFrame.new(origin + Vector3.new(node.X, 0, node.Z)))
			room.Parent = geometry
			roomModels[node.Id], used[node.Id] = room, {}
		end
		for index, edge in ipairs(graph.Edges) do
			used[edge.A][edge.Direction], used[edge.B][edge.Opposite] = true, true
			local a, b = graph.Nodes[edge.A], graph.Nodes[edge.B]
			local middle = origin + Vector3.new((a.X + b.X) / 2, 0, (a.Z + b.Z) / 2)
			local direction = Planner.Directions[edge.Direction]
			local cf = CFrame.lookAt(middle, middle + Vector3.new(direction.X, 0, direction.Z))
			local connector = Instance.new("Model")
			connector.Name, connector.ModelStreamingMode, connector.Parent =
				"Connector_" .. index, Enum.ModelStreamingMode.Atomic, geometry
			connector:SetAttribute("RoomA", edge.A)
			connector:SetAttribute("RoomB", edge.B)
			Builder.Part(
				connector,
				"Floor",
				Vector3.new(28, 2, 32),
				cf * CFrame.new(0, -1, 0),
				Builder.Colors.Wood,
				true,
				Enum.Material.Wood
			)
			for _, x in ipairs({ -13, 13 }) do
				Builder.Part(
					connector,
					"Rail",
					Vector3.new(2, 8, 32),
					cf * CFrame.new(x, 4, 0),
					Builder.Colors.Cream,
					true
				)
			end
		end
		for id, room in pairs(roomModels) do
			for _, socket in ipairs(room.Sockets:GetChildren()) do
				local direction = socket:GetAttribute("Direction")
				socket:SetAttribute("Connected", used[id][direction] == true)
				if not used[id][direction] then
					Builder.Part(
						room.Collision,
						"SealedSocket",
						Vector3.new(24, 8, 2),
						socket.CFrame * CFrame.new(0, -8, 1),
						Builder.Colors.Cream,
						true
					)
				end
			end
		end
		local entryPoint, extractionPoint
		for _, object in ipairs(roomModels[graph.Entry]:GetDescendants()) do
			if CollectionService:HasTag(object, "PlayerSpawn") then
				entryPoint = object
			end
		end
		for _, object in ipairs(roomModels[graph.Extraction]:GetDescendants()) do
			if CollectionService:HasTag(object, "ExtractionPoint") then
				extractionPoint = object
			end
		end
		assert(entryPoint and extractionPoint, "Missing runtime endpoints")
		-- Endpoints stay inside atomic room models. Gameplay holds traceable metadata.
		gameplay:SetAttribute("EntryRoom", graph.Entry)
		gameplay:SetAttribute("ExtractionRoom", graph.Extraction)
		for _, object in ipairs(model:GetDescendants()) do
			object:SetAttribute("RiftId", request.RiftId)
		end
		local stats = Generator.Statistics(model)
		assert(stats.BaseParts <= Constants.MaxPartsPerRift, "Rift exceeds part budget")
		stats.GenerationMilliseconds = (os.clock() - started) * 1000
		for key, value in pairs(stats) do
			model:SetAttribute(key, value)
		end
		model:SetAttribute("State", "Ready")
		model.Parent = parent -- Publish only after all validation/assembly succeeds.
		return {
			Model = model,
			Graph = graph,
			Rooms = roomModels,
			Entry = entryPoint,
			Extraction = extractionPoint,
			Statistics = stats,
		}
	end)
	if not ok then
		model:Destroy()
		error(result, 0)
	end
	return result
end
return Generator
]=],
    ["server/RiftService"] = [=[
--!strict
local Players = game:GetService("Players")
local HttpService = game:GetService("HttpService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local sharedRef = script.Parent:FindFirstChild("SharedRef")
local Shared = sharedRef and sharedRef.Value or ReplicatedStorage:WaitForChild("OddvaultShared")
local Constants = require(Shared.Constants)
local Allocator = require(script.Parent.RiftCellAllocator)
local Generator = require(script.Parent.RiftGenerator)
local Service = {}
export type Rift = {
	RiftId: string,
	Lease: Allocator.Lease,
	Generated: Generator.Generated,
	State: string,
	CreatedAt: number,
	ExpiresAt: number,
	Occupants: { [Player]: boolean },
	Connections: { RBXScriptConnection },
	InstabilityLevel: number,
}
-- Dynamic Instance child access is confined to the standalone package boundary.
export type RiftService = typeof(setmetatable({} :: any, Service))
Service.__index = Service

local function rootOf(player: Player)
	local character = player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if not root or not humanoid or humanoid.Health <= 0 then
		return nil
	end
	return root, humanoid, character
end

function Service.new(world: Model, templates: Folder, remotes: Folder): RiftService
	return setmetatable({
		World = world,
		Templates = templates,
		Remotes = remotes,
		Allocator = Allocator.new(Constants.Cells),
		Rifts = {},
		Pending = {},
		Membership = {},
		Cooldowns = {},
		AckLimits = {},
		Connections = {},
		Running = false,
	}, Service)
end

function Service.Notify(self: RiftService, player: Player, message: string)
	if player.Parent == Players then
		self.Remotes.Notice:FireClient(player, message)
	end
end

function Service.Create(self: RiftService, dimensionId: string, seed: number): (Rift?, string?)
	local riftId = HttpService:GenerateGUID(false)
	local lease, allocationError = self.Allocator:Reserve(riftId)
	if not lease then
		return nil, allocationError
	end
	local ok, generated = pcall(Generator.Generate, self.Templates, self.World.RiftRuntime, {
		RiftId = riftId,
		DimensionId = dimensionId,
		Seed = seed,
		Difficulty = 1,
		PartyId = "Open_" .. riftId,
		CellId = lease.CellId,
		Origin = Vector3.new(lease.X, 0, lease.Z),
	})
	if not ok then
		self.Allocator:Release(lease)
		warn("[Oddvault] Generation rejected", dimensionId, seed, generated)
		return nil, "Room validation failed. Check the server Output."
	end
	local now = os.clock()
	local rift = {
		RiftId = riftId,
		Lease = lease,
		Generated = generated,
		State = "Ready",
		CreatedAt = now,
		ExpiresAt = now + Constants.ReadyLifetime,
		Occupants = {},
		Connections = {},
		InstabilityLevel = 0,
	}
	self.Rifts[riftId] = rift
	local prompt = Instance.new("ProximityPrompt")
	prompt.ActionText, prompt.ObjectText = "Return home", "EXTRACTION GATE"
	prompt.MaxActivationDistance, prompt.HoldDuration, prompt.RequiresLineOfSight = 12, 0.3, false
	prompt:SetAttribute("RiftId", riftId)
	prompt.Parent = generated.Extraction
	table.insert(
		rift.Connections,
		prompt.Triggered:Connect(function(player)
			self:Extract(player, rift)
		end)
	)
	return rift
end

function Service.FinishPending(
	self: RiftService,
	player: Player,
	success: boolean,
	message: string?
)
	local pending = self.Pending[player]
	if not pending then
		return
	end
	self.Pending[player] = nil
	if pending.Humanoid.Parent and pending.Humanoid.Health > 0 then
		pending.Humanoid.WalkSpeed, pending.Humanoid.JumpPower, pending.Humanoid.JumpHeight =
			pending.WalkSpeed, pending.JumpPower, pending.JumpHeight
	end
	if player.Parent == Players then
		self.Remotes.TransitionDone:FireClient(player, pending.Token, success, message or "")
	end
end

function Service.Leave(self: RiftService, player: Player)
	local id = self.Membership[player]
	self.Membership[player] = nil
	player:SetAttribute("OddvaultRiftId", nil)
	local rift = id and self.Rifts[id]
	if rift then
		rift.Occupants[player] = nil
		if rift.State == "Active" and not next(rift.Occupants) then
			self:Close(rift, "Last player left")
		end
	end
end

function Service.Close(self: RiftService, rift: Rift, reason: string)
	if rift.State == "Destroyed" or rift.State == "Closing" then
		return
	end
	rift.State = "Closing"
	rift.Generated.Model:SetAttribute("State", "Closing")
	for player, pending in pairs(self.Pending) do
		if pending.Rift == rift then
			self:FinishPending(player, false, "Rift closed")
		end
	end
	-- Emergency return at expiry uses the known safe hub, never a client destination.
	-- The hub is per-player persistent while they are away; regular extraction still pre-streams.
	for player in pairs(rift.Occupants) do
		self.Membership[player] = nil
		player:SetAttribute("OddvaultRiftId", nil)
		local root, _, character = rootOf(player)
		if root then
			character:PivotTo(CFrame.new(self.World.Hub.HomeArrival.Position))
			root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
		end
		self:Notify(
			player,
			reason == "Run expired" and "The test Rift closed. Back home safely." or "Rift closed."
		)
	end
	table.clear(rift.Occupants)
	for _, connection in ipairs(rift.Connections) do
		connection:Disconnect()
	end
	table.clear(rift.Connections)
	rift.Generated.Model:Destroy()
	assert(self.Allocator:Release(rift.Lease), "Cell lease was lost")
	self.Rifts[rift.RiftId], rift.State = nil, "Destroyed"
end

function Service.Capacity(self: RiftService, rift: Rift): boolean
	local count = 0
	for _ in pairs(rift.Occupants) do
		count += 1
	end
	for _, pending in pairs(self.Pending) do
		if pending.Rift == rift and pending.Entering then
			count += 1
		end
	end
	return count < Constants.MaxOccupants
end

function Service.Transition(
	self: RiftService,
	player: Player,
	rift: Rift,
	entering: boolean,
	source: BasePart
): boolean
	local root, humanoid, character = rootOf(player)
	if not root or self.Pending[player] or (root.Position - source.Position).Magnitude > 14 then
		return false
	end
	if entering then
		if
			self.Membership[player]
			or (rift.State ~= "Ready" and rift.State ~= "Active")
			or not self:Capacity(rift)
		then
			return false
		end
	else
		if self.Membership[player] ~= rift.RiftId or rift.State ~= "Active" then
			return false
		end
	end
	local destination = entering and rift.Generated.Entry.Position
		or self.World.Hub.HomeArrival.Position
	local pending = {
		Token = HttpService:GenerateGUID(false),
		Rift = rift,
		Entering = entering,
		Source = source,
		Destination = destination,
		Character = character,
		Humanoid = humanoid,
		Deadline = os.clock() + Constants.TransitionTimeout,
		WalkSpeed = humanoid.WalkSpeed,
		JumpPower = humanoid.JumpPower,
		JumpHeight = humanoid.JumpHeight,
	}
	self.Pending[player] = pending
	humanoid.WalkSpeed, humanoid.JumpPower, humanoid.JumpHeight = 0, 0, 0
	self.Remotes.Transition:FireClient(player, {
		Token = pending.Token,
		Position = destination,
		Entering = entering,
		RiftId = rift.RiftId,
		RoomName = rift.Generated.Rooms[rift.Generated.Graph.Entry].Name,
	})
	return true
end

function Service.Enter(self: RiftService, player: Player, joinExisting: boolean, source: BasePart)
	if self.Pending[player] or self.Membership[player] then
		return
	end
	local root = rootOf(player)
	if not root or (root.Position - source.Position).Magnitude > 14 then
		return
	end
	local now = os.clock()
	if now < (self.Cooldowns[player] or 0) then
		return
	end
	self.Cooldowns[player] = now + 2
	local rift
	local claimed = {}
	for _, pending in pairs(self.Pending) do
		if pending.Entering then
			claimed[pending.Rift.RiftId] = true
		end
	end
	for _, candidate in pairs(self.Rifts) do
		if
			self:Capacity(candidate)
			and (joinExisting or not claimed[candidate.RiftId])
			and (candidate.State == "Ready" or (joinExisting and candidate.State == "Active"))
		then
			if not rift or candidate.CreatedAt < rift.CreatedAt then
				rift = candidate
			end
		end
	end
	if not rift and joinExisting then
		self:Notify(player, "No open expedition yet. Use the main portal.")
		return
	end
	if not rift then
		local generationError
		rift, generationError =
			self:Create("GiantsKitchen", Random.new():NextInteger(0, 2147483645))
		if not rift then
			self:Notify(player, generationError or "Rifts are busy. Try again shortly.")
			return
		end
	end
	if not self:Transition(player, rift, true, source) then
		self:Notify(player, "Portal unavailable. Try again.")
	end
end

function Service.Extract(self: RiftService, player: Player, rift: Rift)
	if not self:Transition(player, rift, false, rift.Generated.Extraction) then
		return
	end
end

function Service.Acknowledge(self: RiftService, player: Player, token: unknown, ready: unknown)
	-- This remote has no position, artifact identity, inventory or reward argument.
	local now = os.clock()
	local bucket = self.AckLimits[player]
	if not bucket or now - bucket.Start >= 1 then
		bucket = { Start = now, Count = 0 }
		self.AckLimits[player] = bucket
	end
	bucket.Count += 1
	if bucket.Count > 8 then
		return
	end
	if type(token) ~= "string" or #token > 64 or type(ready) ~= "boolean" then
		return
	end
	local pending = self.Pending[player]
	if not pending or pending.Token ~= token then
		return
	end
	local root, _, character = rootOf(player)
	local valid = ready
		and os.clock() <= pending.Deadline
		and character == pending.Character
		and root
		and pending.Source.Parent
		and (root.Position - pending.Source.Position).Magnitude <= 14
		and self.Rifts[pending.Rift.RiftId] == pending.Rift
		and (pending.Rift.State == "Ready" or pending.Rift.State == "Active")
	if not valid then
		self:FinishPending(player, false, "Destination did not stream in time. Try again.")
		return
	end
	local rift, entering = pending.Rift, pending.Entering
	if not entering and self.Membership[player] ~= rift.RiftId then
		self:FinishPending(player, false, "Expedition state changed")
		return
	end
	character:PivotTo(
		CFrame.lookAt(pending.Destination, pending.Destination + Vector3.new(0, 0, 1))
	)
	root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
	if entering then
		if rift.State == "Ready" then
			rift.ExpiresAt = os.clock() + Constants.RunLifetime
		end
		rift.State, rift.Occupants[player], self.Membership[player] = "Active", true, rift.RiftId
		rift.Generated.Model:SetAttribute("State", "Active")
		player:SetAttribute("OddvaultRiftId", rift.RiftId)
		self:FinishPending(player, true, "Follow the countertop to the cyan extraction gate.")
	else
		self:FinishPending(player, true, "Route complete. Artifact recovery arrives in Phase 2.")
		self:Leave(player)
	end
end

function Service.Tick(self: RiftService, now: number)
	for player, pending in pairs(self.Pending) do
		if now > pending.Deadline then
			self:FinishPending(player, false, "Portal timed out. Try again.")
		end
	end
	local closing = {}
	for _, rift in pairs(self.Rifts) do
		if now >= rift.ExpiresAt then
			table.insert(closing, rift)
		elseif rift.State == "Active" then
			-- Phase 1 diagnostics only: no fake promise of active hazards.
			rift.InstabilityLevel =
				math.clamp(100 * (1 - (rift.ExpiresAt - now) / Constants.RunLifetime), 0, 100)
			rift.Generated.Model:SetAttribute("InstabilityLevel", rift.InstabilityLevel)
		end
	end
	for _, rift in ipairs(closing) do
		self:Close(rift, rift.State == "Active" and "Run expired" or "Unused Rift expired")
	end
end

function Service.Start(self: RiftService)
	assert(not self.Running, "RiftService already started")
	self.Running = true
	-- Keeping only the small hub persistent ensures emergency returns have a floor.
	self.World.Hub.ModelStreamingMode = Enum.ModelStreamingMode.Persistent
	local function promptAt(marker, action, callback)
		local prompt = Instance.new("ProximityPrompt")
		prompt.ActionText, prompt.ObjectText = action, "GIANT'S KITCHEN"
		prompt.RequiresLineOfSight, prompt.HoldDuration, prompt.MaxActivationDistance =
			false, 0.25, 12
		prompt.Parent = marker
		table.insert(self.Connections, prompt.Triggered:Connect(callback))
	end
	promptAt(self.World.Hub.PortalEntry, "Enter a new Rift", function(player)
		self:Enter(player, false, self.World.Hub.PortalEntry)
	end)
	local join = self.World.Hub:FindFirstChild("JoinEntry")
	if join then
		promptAt(join, "Join an open Rift", function(player)
			self:Enter(player, true, join)
		end)
	end
	local map = self.World:FindFirstChild("DimensionMap")
	local tour = map and map:FindFirstChild("TourPoints")
	local exit = tour and tour:FindFirstChild("Extraction")
	if exit then
		local prompt = Instance.new("ProximityPrompt")
		prompt.ActionText, prompt.ObjectText = "Return to museum", "EXTRACTION"
		prompt.RequiresLineOfSight, prompt.HoldDuration, prompt.MaxActivationDistance =
			false, 0.3, 12
		prompt.Parent = exit
		table.insert(
			self.Connections,
			prompt.Triggered:Connect(function(player)
				local root, _, character = rootOf(player)
				if
					root
					and not self.Membership[player]
					and not self.Pending[player]
					and (root.Position - exit.Position).Magnitude <= 14
				then
					character:PivotTo(CFrame.new(self.World.Hub.HomeArrival.Position))
					root.AssemblyLinearVelocity, root.AssemblyAngularVelocity =
						Vector3.zero, Vector3.zero
				end
			end)
		)
	end
	table.insert(
		self.Connections,
		self.Remotes.StreamReady.OnServerEvent:Connect(function(player, token, ready)
			self:Acknowledge(player, token, ready)
		end)
	)
	local function added(player)
		player.RespawnLocation = self.World.Hub.OddvaultSpawn
		local function reset()
			self:FinishPending(player, false, "Character respawned")
			self:Leave(player)
		end
		local function characterAdded(character)
			reset()
			task.defer(function()
				local root = character:WaitForChild("HumanoidRootPart", 10)
				if
					root
					and player.Character == character
					and not self.Membership[player]
					and not self.Pending[player]
				then
					character:PivotTo(
						CFrame.lookAt(
							self.World.Hub.OddvaultSpawn.Position + Vector3.new(0, 4, 0),
							self.World.Hub.PortalEntry.Position
						)
					)
				end
			end)
		end
		local connections = {
			player.CharacterRemoving:Connect(reset),
			player.CharacterAdded:Connect(characterAdded),
		}
		self.PlayerConnections[player] = connections
		if player.Character then
			characterAdded(player.Character)
		end
	end
	self.PlayerConnections = {}
	table.insert(self.Connections, Players.PlayerAdded:Connect(added))
	table.insert(
		self.Connections,
		Players.PlayerRemoving:Connect(function(player)
			self:FinishPending(player, false)
			self:Leave(player)
			self.Cooldowns[player] = nil
			self.AckLimits[player] = nil
			for _, connection in ipairs(self.PlayerConnections[player] or {}) do
				connection:Disconnect()
			end
			self.PlayerConnections[player] = nil
		end)
	)
	for _, player in ipairs(Players:GetPlayers()) do
		added(player)
	end
	task.spawn(function()
		while self.Running do
			self:Tick(os.clock())
			task.wait(0.5)
		end
	end)
	local rift, reason = self:Create("GiantsKitchen", 12345)
	if not rift then
		warn("[Oddvault] Initial generation failed:", reason)
	end
end

function Service.Stop(self: RiftService)
	self.Running = false
	local rifts = {}
	for _, rift in pairs(self.Rifts) do
		table.insert(rifts, rift)
	end
	for _, rift in ipairs(rifts) do
		self:Close(rift, "Server stopping")
	end
	for _, connection in ipairs(self.Connections) do
		connection:Disconnect()
	end
	for _, connections in pairs(self.PlayerConnections or {}) do
		for _, connection in ipairs(connections) do
			connection:Disconnect()
		end
	end
	table.clear(self.Connections)
end
return Service
